const crypto = require('crypto');
const secret = $env.AUTOMATION_SECRET;
if (!secret) throw new Error('AUTOMATION_SECRET is required');
async function post(path, data) {
 const body = JSON.stringify(data), timestamp = String(Date.now());
 const signature = crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
 const url = new URL(path, $env.CONVEX_SITE_URL);
 const transport = require(url.protocol === 'https:' ? 'https' : 'http');
 return await new Promise((resolve,reject)=>{
  const req=transport.request(url,{method:'POST',headers:{'content-type':'application/json','content-length':Buffer.byteLength(body),'x-timestamp':timestamp,'x-signature':signature}},res=>{let result='';res.on('data',chunk=>result+=chunk);res.on('end',()=>{if(res.statusCode<200||res.statusCode>=300)return reject(new Error('Convex HTTP '+res.statusCode));try{resolve(JSON.parse(result))}catch(e){reject(e)}})});
  req.setTimeout(15000,()=>req.destroy(new Error('Request timeout')));req.on('error',reject);req.end(body);
 });
}
const item=$input.first().json;
const data=item.body, timestamp=item.headers['x-timestamp'], supplied=item.headers['x-signature'] || '';
if(!timestamp || !Number.isFinite(Number(timestamp)) || Math.abs(Date.now()-Number(timestamp))>300000 || !/^[a-f0-9]{64}$/.test(supplied))throw new Error('Invalid signature or expired timestamp');
const expected=crypto.createHmac('sha256',secret).update(timestamp+'.'+JSON.stringify(data)).digest();
if(!crypto.timingSafeEqual(expected,Buffer.from(supplied,'hex')))throw new Error('Unauthorized');
// Durable mock notification: Convex atomically records the notification once.
await post('/automation/receipt',{key:data.key,loanId:data.loanId,kind:data.kind});
return [{json:{ok:true}}];
